package de.jpx3.intave.packet.nativeapi.wrappers;
import java.util.*;
public class WrappedGameProfile { private final Object handle; private final UUID uuid; private final String name; private final Map<String,Collection<WrappedSignedProperty>> properties=new HashMap<>(); public WrappedGameProfile(UUID id,String name){this.uuid=id;this.name=name;this.handle=this;} public WrappedGameProfile(Object handle){this.handle=handle;this.uuid=null;this.name=String.valueOf(handle);} public UUID getUUID(){return uuid;} public String getName(){return name;} public Object getHandle(){return handle;} public PropertyMap getProperties(){return new PropertyMap(properties);} public static final class PropertyMap { private final Map<String,Collection<WrappedSignedProperty>> map; PropertyMap(Map<String,Collection<WrappedSignedProperty>> m){map=m;} public void put(String k,WrappedSignedProperty v){map.computeIfAbsent(k,x->new ArrayList<>()).add(v);} public Collection<WrappedSignedProperty> get(String k){return map.getOrDefault(k,Collections.emptyList());} }
}
